const parkAgentRun = `-- name: ParkAgentRun :exec
UPDATE agent_run SET status = 'queued', runtime_id = NULL, prepare_lease_expires_at = NULL, started_at = NULL,
  cost_usd = cost_usd + $1, error = $2, failure_reason = $3, infra_failures = infra_failures + 1,
  retry_after = now() + CASE infra_failures WHEN 0 THEN interval '30 seconds' WHEN 1 THEN interval '2 minutes' ELSE interval '10 minutes' END
WHERE id = $4 AND workspace_id = $5
`

type ParkAgentRunParams struct {
	CostUsd       float64   `json:"cost_usd"`
	Error         string    `json:"error"`
	FailureReason *string   `json:"failure_reason"`
	ID            uuid.UUID `json:"id"`
	WorkspaceID   uuid.UUID `json:"workspace_id"`
}

// ParkAgentRun requeues a run behind a growing backoff without spending an attempt.
func (q *Queries) ParkAgentRun(ctx context.Context, arg ParkAgentRunParams) error {
	_, err := q.db.Exec(ctx, parkAgentRun,
		arg.CostUsd,
		arg.Error,
		arg.FailureReason,
		arg.ID,
		arg.WorkspaceID,
	)
	return err
}

const parkedAgentRuns = `-- name: ParkedAgentRuns :many
SELECT id FROM agent_run
WHERE workspace_id = $1 AND card_id = $2::uuid AND status = 'queued' AND infra_failures >= $3
`

type ParkedAgentRunsParams struct {
	WorkspaceID uuid.UUID `json:"workspace_id"`
	CardID      uuid.UUID `json:"card_id"`
	ParkLimit   int32     `json:"park_limit"`
}

// A study's runs held after too many parks try again from a fresh count.
// A study's runs held after too many parks, waiting for its owner.
func (q *Queries) ParkedAgentRuns(ctx context.Context, arg ParkedAgentRunsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, parkedAgentRuns, arg.WorkspaceID, arg.CardID, arg.ParkLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

