func (q *Queries) SweepRuntimes(ctx context.Context, stale pgtype.Interval) (int32, error) {
	row := q.db.QueryRow(ctx, sweepRuntimes, stale)
	var n int32
	err := row.Scan(&n)
	return n, err
}

